questionvariables.text:
aa: 1+rand(4); bb: 2+aa; cc:rand(4);
func_var_u:rand([bb*cc+x*aa, aa+bb*x]); /*this is what will become  u in the question func*/

func_var_dv:e^(aa*x/bb);  /*varible for dv in the question func*/
diff_u2:diff((aa*x/bb),x);


question_func:(func_var_u)*(func_var_dv);     /* questoin expression in terms of u \times dv*/
lower_limit:rand(4);
upper_limit:1+rand(3)+lower_limit;


/*Model answers*/
model_ta:int(question_func,x,lower_limit,upper_limit);   /*force simplification of model answer*/
ta:ratsimp(model_ta);

/*Worked out solution codes*/
diff_u:diff(func_var_u)/del(x);    /* derivative of var_u */
int_v: int(func_var_dv,x);    /* integral of dv to get v */
v_du: int_v*diff_u;              /* porduct  (diff_u and int_v) */ 
int_v_du: int(v_du,x);         /* integral of _ porduct  (diff_u and int_v) */
func:func_var_u*int_v;
func_subt_upper_limit:subst(upper_limit,x,func);
func_subt_lower_limit:subst(lower_limit,x,func);
func_substx:func_subt_upper_limit-func_subt_lower_limit;

func_subt_upper_limit_1:subst(upper_limit,x,int_v_du);
func_subt_lower_limit_1:subst(lower_limit,x,int_v_du);

feedbackvariables.text:
/*Node1- checking for correct answer*/

/*Node 2: mistake_ computing indefinite integral and adding the constant after integration*/
sans_1: int(question_func,x)+c;

/*Node 3: mistake_  Interchanging the limits of integration, however, with the correct definite integral */
sans_2: int(question_func,x,upper_limit,lower_limit); 

/*Node 4: mistake_  computing indefinite integral without the constant */
sans_3:  int(question_func,x)+c;

/*Node 5: mistake_  computing definite integral correctly but with a constant */
sans_4: int(question_func,x,lower_limit,upper_limit)+c;
